// План specs/android-app.md 3.3 / 3.4 (#24c5b2). Pre-Prod, preprod-ttp (TTP Test Locks), EN.
// 3.3 — веб-эмуляция Pixel 7 (то же приложение в браузере): без сети Create Lead → тост «No internet connection / Nothing was saved…»
// не закрывает заголовок и кнопку меню, меню открывается при показанном тосте, тост закрывается крестиком.
// 3.4 — настоящий тап adb по бургеру в APK: нужен Android через CDP, записан как skip.
// Лид НЕ сохраняется: Create Lead нажимается только без сети (как в create-lead-offline-message.spec.ts).
// Не сверено с сайтом при записи: подпись кнопки закрытия тоста (ищем close/dismiss/×), контейнер тоста по тексту.
import { test, expect } from '../../fixtures';
import { OFFLINE_SAVE, ROLE, TEST_PHONE, goOffline, offlineSaveMessage, pp, setEnglish, stamp } from './offline-helpers';

const OPEN_NAV = /Open navigation|^More$/;

test.describe('Android app — offline toast does not cover the header (#24c5b2)', () => {
  test('Offline Create Lead: toast sits below the header, burger opens the menu while the toast is shown, X closes the toast #24c5b2 @android', async ({ asUser }) => {
    const page = await asUser(ROLE);
    const name = `QA-AUTO offline toast #24c5b2 ${stamp()}`;
    try {
      await setEnglish(page);
      await page.goto(pp('/CreateLead'));
      const save = page.getByRole('button', { name: 'Create Lead' });
      await expect(save).toBeVisible({ timeout: 30_000 });
      const client = page.getByPlaceholder('Search clients...').first();
      await client.fill(name);
      await client.press('Escape');
      await page.getByPlaceholder('(234) 567-8900').first().fill(TEST_PHONE);

      await goOffline(page);
      await save.click();
      const msg = offlineSaveMessage(page);
      await expect(msg).toBeVisible();

      // Т1: тост ниже заголовка — не пересекает бургер (источник: «מה רצוי» — לא מכסה את כפתור התפריט והכותרת)
      const burger = page.getByRole('button', { name: OPEN_NAV }).filter({ visible: true }).first();
      await expect(burger).toBeVisible();
      const toast = page.locator('li, [role="status"], [data-sonner-toast]').filter({ hasText: OFFLINE_SAVE }).first();
      const tb = (await toast.boundingBox())!;
      const bb = (await burger.boundingBox())!;
      expect(tb, 'у тоста есть размеры').not.toBeNull();
      expect(tb.y, 'верх тоста не выше низа кнопки меню (не накрывает заголовок)').toBeGreaterThanOrEqual(bb.y + bb.height - 1);

      // Т2: пока тост на экране — меню открывается с первого нажатия
      await burger.click();
      await expect(page.getByRole('link', { name: 'Home', exact: true }).filter({ visible: true }).first()).toBeVisible();
      await page.keyboard.press('Escape');

      // Т3: тост закрывается по X
      const close = toast.getByRole('button', { name: /close|dismiss|×|✕|x/i }).first();
      if (await toast.isVisible()) {
        await close.click();
        await expect(msg).toBeHidden();
      }
    } finally {
      await page.context().setOffline(false);
      if (!page.isClosed()) await page.goto(pp('/Leads')).catch(() => {});
    }
  });

  test.describe('real device', () => {
    test.skip(true, 'нужен Android через CDP: тап adb по бургеру в APK при показанном тосте (Xiaomi Redmi Note 12 / эмулятор)');
    test('adb tap on the burger opens the menu while the offline toast is visible #24c5b2 @android', async () => {
      // Техника: Techory Dev → авиарежим → Create new → New Lead → Create Lead → тост под шапкой → adb input tap по бургеру → меню открыто.
    });
  });
});
